using System;using System.Collections.Generic;using UnityEngine;
namespace AshenCrown.Progression{[Serializable]public class SkillNode{public string id;public string displayKey;public int cost=1;public string[] prerequisites;public bool unlocked;}
public sealed class SkillTreeSystem:MonoBehaviour{public static SkillTreeSystem Instance{get;private set;}public event Action<string> SkillUnlocked;public IReadOnlyList<SkillNode> Nodes=>nodes;[SerializeField]List<SkillNode> nodes=new List<SkillNode>();public int SkillPoints{get;private set;}
void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);if(nodes.Count==0)BuildDefaultTree();}public void AddSkillPoints(int n)=>SkillPoints=Mathf.Max(0,SkillPoints+n);public bool IsUnlocked(string id){var n=Find(id);return n!=null&&n.unlocked;}
public bool CanUnlock(string id){var n=Find(id);if(n==null||n.unlocked||SkillPoints<n.cost)return false;if(n.prerequisites==null)return true;foreach(var p in n.prerequisites)if(!IsUnlocked(p))return false;return true;}
public bool Unlock(string id){if(!CanUnlock(id))return false;var n=Find(id);SkillPoints-=n.cost;n.unlocked=true;SkillUnlocked?.Invoke(id);return true;}public List<string> CaptureUnlocked(){var r=new List<string>();foreach(var n in nodes)if(n.unlocked)r.Add(n.id);return r;}public void Restore(List<string> u,int p){SkillPoints=Mathf.Max(0,p);foreach(var n in nodes)n.unlocked=u!=null&&u.Contains(n.id);}
void BuildDefaultTree(){nodes=new List<SkillNode>{new SkillNode{id="ashen_edge",displayKey="skill.ashen_edge",cost=1},new SkillNode{id="void_step",displayKey="skill.void_step",cost=1,prerequisites=new[]{"ashen_edge"}},new SkillNode{id="ember_guard",displayKey="skill.ember_guard",cost=2,prerequisites=new[]{"ashen_edge"}},new SkillNode{id="crown_breaker",displayKey="skill.crown_breaker",cost=3,prerequisites=new[]{"void_step","ember_guard"}}};}SkillNode Find(string id){foreach(var n in nodes)if(n.id==id)return n;return null;}}}